class Solution:

	def findMinInsertions(self, S):
		m = len(S)
		b = S[::-1]
		n = len(b)
		t = [[0 for i in range(n + 1)] for j in range(m + 1)]
		for i in range(1, m + 1):
			for j in range(1, n + 1):
				if S[i - 1] == b[j - 1]:
					t[i][j] = 1 + t[i - 1][j - 1]
				else:
					t[i][j] = max(t[i][j - 1], t[i - 1][j])
		lps = t[m][n]
		return len(S) - lps
